steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        issueLabels(name: \"Regression\") {
          nodes {
            id
            name
            group
          }
        }
        issue(identifier: \"MOB-3\") {
          id
          identifier
          labelIds
        }
      }
    "
  }'
